import numpy as np


def heilbronn_convex13() -> np.ndarray:
    """
    Deterministically optimize a 13-point Heilbronn configuration in an
    equilateral triangular hull using a centre point and three 3-fold orbits.
    A fixed-seed annealing search is followed by exact maximin polishing.
    """
    rng = np.random.default_rng(13031957)

    # An affine normalization means that an equilateral hull is sufficient:
    # all triangle-area / hull-area ratios are affine invariant.
    radius = 1.0 / np.sqrt(3.0)
    angles = np.pi / 2.0 + 2.0 * np.pi * np.arange(3) / 3.0
    outer = radius * np.column_stack((np.cos(angles), np.sin(angles)))
    centre = np.array([[0.0, 0.0]])
    hull_det = abs(np.cross(outer[1] - outer[0], outer[2] - outer[0]))

    triples = np.array([
        (i, j, k)
        for i in range(13)
        for j in range(i + 1, 13)
        for k in range(j + 1, 13)
    ], dtype=np.intp)

    bary_inv = np.linalg.inv(np.column_stack((
        outer[0] - outer[2], outer[1] - outer[2]
    )))

    def inside(r: float, phase: float) -> bool:
        """Check whether one representative orbit point is in the hull."""
        p = np.array((r * np.cos(phase), r * np.sin(phase)))
        b = bary_inv @ (p - outer[2])
        return bool(b[0] >= -1e-12 and b[1] >= -1e-12
                    and b[0] + b[1] <= 1.0 + 1e-12)

    def build(state: np.ndarray) -> np.ndarray:
        """Build centre, hull vertices, and three rotational point orbits."""
        blocks = [centre, outer]
        for ring in range(3):
            r, phase = state[2 * ring:2 * ring + 2]
            a = phase + 2.0 * np.pi * np.arange(3) / 3.0
            blocks.append(r * np.column_stack((np.cos(a), np.sin(a))))
        return np.vstack(blocks)

    def low_tail(state: np.ndarray) -> np.ndarray:
        """Return the fourteen smallest normalized triangle determinant areas."""
        p = build(state)
        a, b, c = p[triples[:, 0]], p[triples[:, 1]], p[triples[:, 2]]
        d = np.abs((b[:, 0] - a[:, 0]) * (c[:, 1] - a[:, 1])
                   - (b[:, 1] - a[:, 1]) * (c[:, 0] - a[:, 0])) / hull_det
        return np.partition(d, 13)[:14]

    def value(state: np.ndarray) -> float:
        """Evaluate the exact normalized minimum triangle area."""
        return float(np.min(low_tail(state)))

    def merit(state: np.ndarray) -> float:
        """Use the bottleneck plus a lower-tail tie breaker for annealing."""
        low = low_tail(state)
        return float(np.min(low) + 0.18 * np.mean(low))

    best = None
    best_value = -np.inf
    period = 2.0 * np.pi / 3.0

    # Broad deterministic multistart search in only six orbit parameters.
    for _ in range(96):
        state = np.empty(6)
        for ring in range(3):
            phase = rng.uniform(0.0, period)
            limit = radius
            while not inside(limit, phase):
                limit *= 0.985
            state[2 * ring] = rng.uniform(0.055, max(0.056, 0.985 * limit))
            state[2 * ring + 1] = phase

        current = merit(state)
        initial = value(state)
        if initial > best_value:
            best, best_value = state.copy(), initial

        for iteration in range(1600):
            trial = state.copy()
            coordinate = int(rng.integers(6))
            cooling = 1.0 - iteration / 1600.0

            if coordinate % 2 == 0:
                trial[coordinate] = np.clip(
                    trial[coordinate] + rng.normal(0.0, 0.105 * (0.12 + cooling)),
                    0.035, radius
                )
            else:
                trial[coordinate] = (
                    trial[coordinate] + rng.normal(0.0, 0.30 * (0.12 + cooling))
                ) % period

            ring = coordinate // 2
            if not inside(trial[2 * ring], trial[2 * ring + 1]):
                continue

            candidate = merit(trial)
            temperature = 0.0014 * cooling * cooling + 1e-6
            if (candidate >= current or
                    rng.random() < np.exp((candidate - current) / temperature)):
                state, current = trial, candidate
                exact = value(state)
                if exact > best_value:
                    best, best_value = state.copy(), exact

    # Directly polish the nonsmooth objective at decreasing coordinate scales.
    state = best.copy()
    current = value(state)
    r_step, a_step = 0.018, 0.045
    while r_step > 2e-5 or a_step > 2e-5:
        improved = False
        for coordinate in range(6):
            for direction in (-1.0, 1.0):
                trial = state.copy()
                if coordinate % 2 == 0:
                    trial[coordinate] = np.clip(
                        trial[coordinate] + direction * r_step, 0.035, radius
                    )
                else:
                    trial[coordinate] = (
                        trial[coordinate] + direction * a_step
                    ) % period

                ring = coordinate // 2
                if not inside(trial[2 * ring], trial[2 * ring + 1]):
                    continue
                candidate = value(trial)
                if candidate > current + 1e-14:
                    state, current, improved = trial, candidate, True

        if not improved:
            r_step *= 0.5
            a_step *= 0.5

    return build(state)


